// Digital twin for Sense.T.C — Azoteq IQS323 ProxFusion capacitive touch.
//
// A counts-based charge-transfer cap sensor (NOT a femtofarad CDC — it reports
// filtered conversion counts vs a long-term-average baseline, never absolute
// capacitance). This is a DOUBLE-SIDED tile: the IC + passives are on the
// bottom; the ENTIRE TOP SURFACE is the self-cap electrode for channel CH1 (via
// a 470Ω series R), and CH0 is a second external electrode brought out to pad 8.
// CH2 exists in the chip but is unpopulated on this tile.
//
// Pad map (Sense-T-C-a.json): GND (1), RDY/MCLR (3, open-drain output, on-tile
// 4.7k pull-up + 100nF), I2C (4/5), C0 external electrode (8), V+ (10).
//
// Modeled: the two touch electrodes are driven by the controls; counts/LTA/delta
// and the System-Status bits follow from them, matching the driver's register
// layout (canonical). The absolute count magnitudes are modeled (inferred); a
// real chip's working point comes from ATI. Slider/gesture are not usable on a
// single-surface tile, so those reads are honest no-ops (hallucinated).
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x44; // order code 001 (per tile JSON)

// Channel indices (driver SENSE_T_C_CH*): 0 = external (pad 8), 1 = surface, 2 = unpopulated.
const CH_EXTERNAL = 0;
const CH_SURFACE = 1;

// Modeled counts: a flat LTA baseline; touch/prox raise counts above it.
const LTA_BASE = 1000;
const TOUCH_DELTA = 220;
const PROX_DELTA = 60;

// Power-mode quiescent current (datasheet §3.4, self-cap 3ch, 3.3V), µA.
const I_NORMAL_UA = 125;
const I_LOW_UA = 38;
const I_ULP_UA = 4;
const I_HALT_UA = 2;

// Power-mode codes (sense_t_c_power_mode_t)
const PM_NORMAL = 0;
const PM_LOW = 1;
const PM_ULP = 2;
const PM_HALT = 3;

// System-status bits (IQS323_STATUS_*): per-channel prox = bit(8+ch*2), touch = bit(9+ch*2).
const ST_PROX_EVENT = 1 << 0;
const ST_TOUCH_EVENT = 1 << 1;
const chProxBit = (ch: number) => 1 << (8 + ch * 2);
const chTouchBit = (ch: number) => 1 << (9 + ch * 2);

const SLIDER_INVALID = 0xffff; // no slider configurable on a single-surface tile

interface State {
  // ── electrodes (driven by controls) ──
  touch_surface: number; // CH1 — whole top face
  touch_external: number; // CH0 — pad 8
  prox_surface: number; // near-but-not-touch on the surface
  prox_external: number;

  // ── config (tracked) ──
  power_mode: number;
  comm_mode: number; // 0 stream, 1 event
  events_mask: number;
  prox_thr: number; // shared threshold model (per-channel in HW)
  touch_thr: number;
  np_rate_ms: number;
  lp_rate_ms: number;
  ulp_rate_ms: number;
  halt_rate_ms: number;
  power_timeout_ms: number;

  [field: string]: number;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

// Per-channel touch/prox state from the modeled electrodes (CH2 is unpopulated).
function touchOf(s: State, ch: number): number {
  if (ch === CH_SURFACE) return s.touch_surface ? 1 : 0;
  if (ch === CH_EXTERNAL) return s.touch_external ? 1 : 0;
  return 0;
}
function proxOf(s: State, ch: number): number {
  if (touchOf(s, ch)) return 1; // touch implies prox
  if (ch === CH_SURFACE) return s.prox_surface ? 1 : 0;
  if (ch === CH_EXTERNAL) return s.prox_external ? 1 : 0;
  return 0;
}
function deltaOf(s: State, ch: number): number {
  if (touchOf(s, ch)) return TOUCH_DELTA;
  if (proxOf(s, ch)) return PROX_DELTA;
  return 0;
}
const countsOf = (s: State, ch: number) => LTA_BASE + deltaOf(s, ch);

// System Status word the driver reads from 0x10.
function statusWord(s: State): number {
  let st = 0;
  for (const ch of [CH_EXTERNAL, CH_SURFACE]) {
    if (proxOf(s, ch)) st |= chProxBit(ch);
    if (touchOf(s, ch)) st |= chTouchBit(ch);
  }
  if (proxOf(s, CH_EXTERNAL) || proxOf(s, CH_SURFACE)) st |= ST_PROX_EVENT;
  if (touchOf(s, CH_EXTERNAL) || touchOf(s, CH_SURFACE)) st |= ST_TOUCH_EVENT;
  return st;
}

const anyTouched = (s: State) => (touchOf(s, CH_EXTERNAL) || touchOf(s, CH_SURFACE) ? 1 : 0);

function modeCurrentUa(mode: number): number {
  switch (mode) {
    case PM_LOW:
      return I_LOW_UA;
    case PM_ULP:
      return I_ULP_UA;
    case PM_HALT:
      return I_HALT_UA;
    default:
      return I_NORMAL_UA; // NORMAL / AUTO / AUTO_NO_ULP active
  }
}

const sim: TileSim<State> = {
  tile: 'Sense.T.C',

  defaultState: {
    touch_surface: 0,
    touch_external: 0,
    prox_surface: 0,
    prox_external: 0,

    power_mode: PM_NORMAL,
    comm_mode: 1, // event mode (chip default)
    events_mask: ST_PROX_EVENT | ST_TOUCH_EVENT,
    prox_thr: 20,
    touch_thr: 40,
    np_rate_ms: 16,
    lp_rate_ms: 60,
    ulp_rate_ms: 160,
    halt_rate_ms: 3000,
    power_timeout_ms: 2000,
  },

  controls: [
    { type: 'toggle', field: 'touch_surface', label: 'Touch top surface (C1)' },
    { type: 'toggle', field: 'touch_external', label: 'Touch C0 (pad 8)' },
    { type: 'toggle', field: 'prox_surface', label: 'Approach surface (prox)' },
    {
      type: 'slider',
      field: 'power_mode',
      label: 'Power mode (0 NP/1 LP/2 ULP/3 Halt)',
      min: 0,
      max: 3,
      step: 1,
    },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_sense_t_c_find: () => ({ scalar: I2C_ADDR }),
    tile_sense_t_c_init: () => ({ scalar: 0, nextState: { power_mode: PM_NORMAL } }),
    tile_sense_t_c_process: ({ state }) => ({ scalar: statusWord(state) }),
    tile_sense_t_c_on_event: () => ({ nextState: {} }),
    tile_sense_t_c_sleep: () => ({ nextState: { power_mode: PM_HALT } }),
    tile_sense_t_c_wake: () => ({ nextState: { power_mode: PM_NORMAL } }),

    // ── status / data ──
    tile_sense_t_c_get_status: ({ state }) => ({ scalar: statusWord(state) }),
    tile_sense_t_c_get_gestures: () => ({ scalar: 0 }), // no gesture surface on this tile
    tile_sense_t_c_is_touched: ({ state, args }) => ({ scalar: touchOf(state, pick(args, 0, 0)) }),
    tile_sense_t_c_is_prox: ({ state, args }) => ({ scalar: proxOf(state, pick(args, 0, 0)) }),
    tile_sense_t_c_is_touched_any: ({ state }) => ({ scalar: anyTouched(state) }),
    tile_sense_t_c_get_counts: ({ state, args }) => ({ scalar: countsOf(state, pick(args, 0, 0)) }),
    tile_sense_t_c_get_lta: () => ({ scalar: LTA_BASE }),
    tile_sense_t_c_get_delta: ({ state, args }) => ({ scalar: deltaOf(state, pick(args, 0, 0)) }),
    tile_sense_t_c_get_slider: () => ({ scalar: SLIDER_INVALID }),
    tile_sense_t_c_read_slider_pct: () => ({ array: [0, 0] }), // [ok, pct] — no slider
    tile_sense_t_c_wait_for_touch: ({ state }) => ({ scalar: anyTouched(state) }),
    tile_sense_t_c_wait_for_gesture: () => ({ scalar: 0 }),

    // ── config ──
    tile_sense_t_c_set_thresholds: ({ args }) => ({
      nextState: {
        prox_thr: clamp(pick(args, 1, 20), 0, 255),
        touch_thr: clamp(pick(args, 2, 40), 0, 255),
      },
    }),
    tile_sense_t_c_set_power_mode: ({ args }) => ({
      nextState: { power_mode: clamp(pick(args, 0, PM_NORMAL), 0, 5) },
    }),
    tile_sense_t_c_enable_events: ({ args }) => ({ nextState: { events_mask: pick(args, 0, 0) } }),
    tile_sense_t_c_ati: () => ({ nextState: {} }),
    tile_sense_t_c_set_ati_setup: () => ({ nextState: {} }),
    tile_sense_t_c_set_counts_filter: () => ({ nextState: {} }),
    tile_sense_t_c_set_conversion_freq: () => ({ nextState: {} }),
    tile_sense_t_c_set_channel_mode: () => ({ nextState: {} }),
    tile_sense_t_c_set_comm_mode: ({ args }) => ({
      nextState: { comm_mode: pick(args, 0, 1) ? 1 : 0 },
    }),

    // ── low-level ──
    tile_sense_t_c_read_reg: () => ({ scalar: 0 }),
    tile_sense_t_c_write_reg: () => ({ nextState: {} }),

    // ── v1.3 additions ──
    tile_sense_t_c_reseed: () => ({ nextState: {} }), // re-snaps LTA to counts; baseline is flat here
    tile_sense_t_c_set_report_rate: ({ args }) => {
      const mode = pick(args, 0, PM_NORMAL);
      const ms = clamp(pick(args, 1, 16), 0, 3000);
      const field =
        mode === PM_LOW
          ? 'lp_rate_ms'
          : mode === PM_ULP
            ? 'ulp_rate_ms'
            : mode === PM_HALT
              ? 'halt_rate_ms'
              : 'np_rate_ms';
      return { nextState: { [field]: ms } };
    },
    tile_sense_t_c_set_power_timeout: ({ args }) => ({
      nextState: { power_timeout_ms: clamp(pick(args, 0, 2000), 0, 65000) },
    }),
    // Nominal tuned working point (divider 31, value ~934) — matches Azoteq EV-kit.
    tile_sense_t_c_get_compensation: () => ({ scalar: (31 << 11) | 934 }),
    tile_sense_t_c_set_compensation: () => ({ nextState: {} }),
  },

  provenance: {
    tile_sense_t_c_find: 'canonical', // I2C 0x44
    tile_sense_t_c_get_status: 'canonical', // System Status bit layout
    tile_sense_t_c_is_touched: 'canonical',
    tile_sense_t_c_is_prox: 'canonical',
    tile_sense_t_c_is_touched_any: 'canonical',
    tile_sense_t_c_get_lta: 'canonical', // LTA register
    tile_sense_t_c_set_power_mode: 'canonical', // SYSTEM_CONTROL[6:4]
    tile_sense_t_c_set_comm_mode: 'canonical', // SYSTEM_CONTROL bit7 (1=event)
    tile_sense_t_c_set_thresholds: 'canonical', // Prox/Touch Settings byte layout
    tile_sense_t_c_reseed: 'canonical', // SYSTEM_CONTROL.RESEED bit3
    tile_sense_t_c_set_report_rate: 'canonical', // 0xC1-0xC4, ms
    tile_sense_t_c_set_power_timeout: 'canonical', // 0xC5, ms
    tile_sense_t_c_get_compensation: 'canonical', // 0x39+ encoding
    tile_sense_t_c_set_compensation: 'canonical',
    // inferred — modeled magnitudes / behavioral stubs
    tile_sense_t_c_get_counts: 'inferred', // modeled count magnitude
    tile_sense_t_c_get_delta: 'inferred',
    tile_sense_t_c_process: 'inferred',
    tile_sense_t_c_ati: 'inferred',
    // hallucinated — not usable on this single-surface tile
    tile_sense_t_c_get_slider: 'hallucinated',
    tile_sense_t_c_read_slider_pct: 'hallucinated',
    tile_sense_t_c_get_gestures: 'hallucinated',
    tile_sense_t_c_wait_for_gesture: 'hallucinated',
    tile_sense_t_c_read_reg: 'hallucinated',
    power: 'canonical', // datasheet §3.4 per-mode current
  },

  // RDY (pad 3) is the one tile-driven digital output: open-drain, asserted LOW
  // on an enabled event in event mode. Shown 1 = asserted for clarity. C0 (pad 8)
  // and the C1 top surface are capacitance sense INPUTS, not driven outputs.
  padOutputs(state) {
    const event = (statusWord(state) & state.events_mask) !== 0;
    const asserted = state.comm_mode === 1 && event ? 1 : 0;
    return { RDY: asserted };
  },

  // Electrical: a pure load on V+ (pad 10) / GND (pad 1). Draw depends on the
  // power mode (datasheet §3.4); no rail is sourced. ULP/Halt collapse to µA.
  power(state) {
    const ua = modeCurrentUa(state.power_mode);
    return {
      draw_ua: ua,
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: 3300,
          i_ua: ua,
          pads: ['10'],
          note: `IQS323 (${['NP', 'LP', 'ULP', 'Halt'][state.power_mode] ?? 'NP'})`,
        },
      ],
    };
  },
};

export default sim;
